    def usage_report(self, *, workspace_id: str, since: datetime.datetime, until: datetime.datetime, metric: Optional[str]) -> Iterator[UsageReportRow]:
        result = self._conn.execute(sqlalchemy.text(USAGE_REPORT), {
            "p1": workspace_id,
            "p2": since,
            "p3": until,
            "p4": metric,
        })
        for row in result:
            yield UsageReportRow(
                sandbox_id=row[0],
                metric=row[1],
                day=row[2],
                quantity=row[3],
            )

